CREATE DEFINER=`root`@`localhost` PROCEDURE `buscar_columnas` (IN `nombre_tabla` VARCHAR(255), IN `busqueda` VARCHAR(255))   BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE nombre_columna VARCHAR(255);
    DECLARE query VARCHAR(2000);
    
    DECLARE cur CURSOR FOR 
        SELECT COLUMN_NAME 
        FROM INFORMATION_SCHEMA.COLUMNS 
        WHERE TABLE_NAME = nombre_tabla AND TABLE_SCHEMA = DATABASE();
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    SET query = CONCAT('SELECT * FROM ', nombre_tabla, ' WHERE ');
    
    OPEN cur;
    leer_columnas: LOOP
        FETCH cur INTO nombre_columna;
        IF done THEN
            LEAVE leer_columnas;
        END IF;
        SET query = CONCAT(query, nombre_columna, ' LIKE "%', busqueda, '%" OR ');
    END LOOP;
    
    CLOSE cur;
    
    SET query = LEFT(query, LENGTH(query) - 4); -- Eliminar el último ' OR '
    SET query = CONCAT(query, ' LIMIT 150;');
    
    PREPARE stmt FROM query;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
END$$

